function isRecord(value) {
  return value && typeof value === 'object' && !Array.isArray(value);
}

function deepMerge(base, override) {
  if (!isRecord(base)) return isRecord(override) ? { ...override } : override ?? base;
  const out = { ...base };
  if (!isRecord(override)) return out;

  for (const [key, value] of Object.entries(override)) {
    if (value === undefined) continue;
    const current = out[key];
    out[key] = isRecord(current) && isRecord(value)
      ? deepMerge(current, value)
      : value;
  }

  return out;
}

const inbound = $input.first()?.json || {};
const inboundBody = isRecord(inbound.body) ? inbound.body : {};
const inboundConfig = isRecord(inbound.CONFIG)
  ? inbound.CONFIG
  : (isRecord(inboundBody.CONFIG) ? inboundBody.CONFIG : {});
const CONFIG = deepMerge(BASE_CONFIG, inboundConfig);

// --- derive basicAuth from client credentials (computed here to avoid expression quirks) ---
try {
  const k = CONFIG?.lulu?.clientKey || '';
  const s = CONFIG?.lulu?.clientSecret || '';
  const b = Buffer.from(`${k}:${s}`).toString('base64');
