for (attempts = 1; attempts <= 3; attempts++){
  try {
    const resp = await http({
      method: 'POST',
      url,
      headers,
      body: payload,
      json: true,
      ignoreHttpStatusErrors: true
    });
    statusCode = Number(resp?.statusCode || resp?.status || 200);
    if (statusCode >= 500 || statusCode === 429){
      lastErr = new Error(`Submit retryable error (status=${statusCode})`);
      if (attempts < 3) await sleep(1000 * Math.pow(2, attempts-1));
      continue;
    }
    if (statusCode >= 400){
      const details = typeof resp === 'object' ? JSON.stringify(resp) : String(resp);
      throw new Error(`Submit 4xx error (status=${statusCode}) — Check source URLs: interior=${interior} cover=${cover} — Body=${details}`);
    }
    // success
    const body = resp;
    const id = body?.id || body?.data?.id || body?.job_id;
    const status = body?.status || body?.data?.status || 'CREATED';
    return [{
      json: {
        ...j,
        id, status,
        luluSubmitStatusCode: statusCode,
        retryCountSubmit: attempts,
        luluSubmitResponse: body
      }
    }];
  } catch (e) {
    lastErr = e;
    if (attempts < 3) await sleep(1000 * Math.pow(2, attempts-1));
  }
}
